// --- shared: Claude Messages API helpers (inlined at build time) -----------
// One model for every LLM route; effort is tuned per route. Structured outputs
// (output_config.format) guarantee schema-valid JSON. Server-side fallbacks
// re-run a declined request on Anthropic's recommended fallback model.
// Any refusal, truncation, HTTP error or bad JSON returns ok=false so the
// caller takes its deterministic path: no LLM sits on a path that moves money.
const CLAUDE_MODEL = 'claude-opus-5-5';
function claudeRequest({ system, user, schema, effort = 'low', maxTokens = 8000 }) {
  return {
    model: CLAUDE_MODEL,
    max_tokens: maxTokens,
    fallbacks: 'default',
    system,
    output_config: { effort, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }],
  };
}
function parseClaude(item) {
  if (!item) return { ok: false, reason: 'no_response' };
  if (item.error) return { ok: false, reason: 'http_error', detail: String(item.error.message ?? item.error).slice(0, 300) };
  const status = item.statusCode;
  const msg = item.body ?? item;
  if (status && (status < 200 || status >= 300)) return { ok: false, reason: `http_${status}`, detail: msg?.error?.type ?? null };
  if (msg?.stop_reason === 'refusal') return { ok: false, reason: 'refusal', detail: msg.stop_details?.category ?? null };
  if (msg?.stop_reason === 'max_tokens') return { ok: false, reason: 'max_tokens' };
  const text = (msg?.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return { ok: true, data: JSON.parse(text), model: msg.model ?? CLAUDE_MODEL, usage: msg.usage ?? null };
  } catch {
    return { ok: false, reason: 'invalid_json' };
  }
}
// --- end shared --------------------------------------------------------------

// Communication agent. It writes from the client's own metrics only. A
// deterministic compliance gate checks the draft before anything is sent;
// tables and the disclosure footer are rendered by code, not by the model.
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['subject', 'summary_md', 'highlights', 'risk_notes'],
  properties: {
    subject: { type: 'string' },
    summary_md: { type: 'string' },
    highlights: { type: 'array', items: { type: 'string' } },
    risk_notes: { type: 'array', items: { type: 'string' } },
  },
};
const system = [
  'You write a short, factual daily account summary for a client of a crypto trading software platform.',
  'Use only the numbers in the data, copied exactly (you may round to two decimals). Describe what happened; do not',
  'predict, promise or imply future results. Never recommend buying, selling, holding or changing allocations,',
  'and never describe trading as safe, guaranteed or low-risk. Mention any risk-mode changes plainly.',
  'Keep summary_md under 120 words, with no links and no headings. Subject under 70 characters.',
].join(' ');
return $input.all().map((it) => ({
  json: {
    ...it.json,
    anthropic_request: claudeRequest({ system, user: { period: it.json.period, metrics: it.json.metrics }, schema, effort: 'medium', maxTokens: 6000 }),
  },
}));

// --- shared: Claude Messages API helpers (inlined at build time) -----------
// One model for every LLM route; effort is tuned per route. Structured outputs
// (output_config.format) guarantee schema-valid JSON. Server-side fallbacks
// re-run a declined request on Anthropic's recommended fallback model.
// Any refusal, truncation, HTTP error or bad JSON returns ok=false so the
// caller takes its deterministic path: no LLM sits on a path that moves money.
const CLAUDE_MODEL = 'claude-opus-5-5';
function claudeRequest({ system, user, schema, effort = 'low', maxTokens = 8000 }) {
  return {
    model: CLAUDE_MODEL,
    max_tokens: maxTokens,
    fallbacks: 'default',
    system,
    output_config: { effort, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }],
  };
}
function parseClaude(item) {
  if (!item) return { ok: false, reason: 'no_response' };
  if (item.error) return { ok: false, reason: 'http_error', detail: String(item.error.message ?? item.error).slice(0, 300) };
  const status = item.statusCode;
  const msg = item.body ?? item;
  if (status && (status < 200 || status >= 300)) return { ok: false, reason: `http_${status}`, detail: msg?.error?.type ?? null };
  if (msg?.stop_reason === 'refusal') return { ok: false, reason: 'refusal', detail: msg.stop_details?.category ?? null };
  if (msg?.stop_reason === 'max_tokens') return { ok: false, reason: 'max_tokens' };
  const text = (msg?.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return { ok: true, data: JSON.parse(text), model: msg.model ?? CLAUDE_MODEL, usage: msg.usage ?? null };
  } catch {
    return { ok: false, reason: 'invalid_json' };
  }
}
// --- end shared --------------------------------------------------------------

// Deterministic compliance gate for client communications:
//  * banned phrases (performance promises, advice, hype)
//  * every number in the draft must exist in the source metrics
//    (anti-hallucination), after ignoring dates and small counts
//  * no links, bounded length
// A failing draft is replaced by the template-only report and flagged.
const BANNED = [
  /guarantee/i, /risk[-\s]?free/i, /can(?:'|no)?t lose/i, /\bno[-\s]?lose\b/i, /sure[-\s]?thing/i,
  /will (?:earn|make|return|gain|profit|outperform|recover)/i, /expected (?:return|profit)s?\b/i,
  /\byou should (?:buy|sell|hold|invest|increase|decrease|add|reduce)/i, /\bwe (?:recommend|suggest|advise)\b/i,
  /\bpassive income\b/i, /\bdouble your\b/i, /\bto the moon\b/i, /\bsafe (?:bet|investment|returns?)\b/i,
];

function numbersInText(text) {
  const cleaned = String(text)
    .replace(/\b\d{4}-\d{2}-\d{2}(?:[T ][\d:.]+Z?)?\b/g, ' ')   // ISO dates and timestamps
    .replace(/\b\d{1,2}:\d{2}(?::\d{2})?\b/g, ' ');            // clock times
  return (cleaned.match(/-?\$?\d[\d,]*(?:\.\d+)?%?/g) ?? [])
    .map((s) => Number(s.replace(/[$,%]/g, '')))
    .filter(Number.isFinite);
}
function collectNumbers(obj, out = []) {
  if (obj === null || obj === undefined) return out;
  if (typeof obj === 'number') out.push(obj);
  else if (typeof obj === 'string' && /^-?\d+(?:\.\d+)?$/.test(obj.trim())) out.push(Number(obj));
  else if (Array.isArray(obj)) obj.forEach((v) => collectNumbers(v, out));
  else if (typeof obj === 'object') Object.values(obj).forEach((v) => collectNumbers(v, out));
  return out;
}
function supported(n, src) {
  if (Number.isInteger(n) && Math.abs(n) <= 12) return true;       // counts, months, small integers
  return src.some((s) => {
    const close = (a, b) => Math.abs(a - b) <= Math.max(0.011, Math.abs(b) * 0.005);
    return close(Math.abs(n), Math.abs(s)) || close(Math.abs(n), Math.abs(s * 100));   // value or percent form
  });
}
function check(draft, metrics) {
  const issues = [];
  const text = [draft?.subject, draft?.summary_md, ...(draft?.highlights ?? []), ...(draft?.risk_notes ?? [])].join('\n');
  for (const re of BANNED) if (re.test(text)) issues.push(`banned_phrase:${re.source}`);
  const src = collectNumbers(metrics);
  const unsupported = numbersInText(text).filter((n) => !supported(n, src));
  if (unsupported.length) issues.push(`unsupported_numbers:${unsupported.slice(0, 5).join(',')}`);
  if (/https?:\/\/|www\./i.test(text)) issues.push('contains_link');
  if (String(draft?.summary_md ?? '').length > 1200) issues.push('too_long');
  if (String(draft?.subject ?? '').length > 90) issues.push('subject_too_long');
  return { pass: issues.length === 0, issues };
}

const requests = $('Build narrative request').all();
return $input.all().map((it, i) => {
  const src = { ...(requests[i]?.json ?? {}) };
  delete src.anthropic_request;
  const t = parseClaude(it.json);
  const result = t.ok ? check(t.data, src.metrics) : { pass: false, issues: [`llm_unavailable:${t.reason}`] };
  return { json: { ...src, draft: t.ok ? t.data : null, compliance: { ...result, model: t.ok ? t.model : null } } };
});

// Renders the report. Tables and the disclosure footer come from code; the
// model's narrative is used only if it passed the compliance gate.
const DISCLOSURE_VERSION = '2026.09';
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const md = (s) => esc(s)
  .split(/\n{2,}/)
  .map((p) => (/^\s*[-*] /m.test(p)
    ? `<ul>${p.split('\n').filter((l) => l.trim()).map((l) => `<li>${l.replace(/^\s*[-*] /, '')}</li>`).join('')}</ul>`
    : `<p>${p.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>')}</p>`))
  .join('');
const usd = (x) => (x === null || x === undefined ? 'n/a' : `USD ${Number(x).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`);

return $input.all().map(({ json: r }) => {
  const accounts = r.metrics?.accounts ?? [];
  const breakers = r.metrics?.breaker_events ?? [];
  const rows = accounts.map((a) => `<tr><td>${esc(a.account_id)}</td><td>${esc(a.venue)}</td><td>${usd(a.equity_usd)}</td>`
    + `<td>${usd(a.day_change_usd)}</td><td>${usd(a.fees_usd)}</td><td>${usd(a.funding_usd)}</td><td>${esc(a.risk_mode)}</td></tr>`).join('');
  const narrative = r.compliance?.pass && r.draft
    ? md(r.draft.summary_md)
    : '<p>Your daily account summary is below. Figures come directly from your connected exchange accounts.</p>';
  const breakerList = breakers.length
    ? `<p><strong>Risk controls that acted:</strong></p><ul>${breakers.map((b) => `<li>${esc(b.ts)} ${esc(b.tier)} ${esc(b.metric ?? '')} ${esc(b.action ?? '')}</li>`).join('')}</ul>`
    : '';
  const subject = r.compliance?.pass && r.draft?.subject ? r.draft.subject : `Your AQOS account summary for ${r.period}`;
  const html = [
    `<p>Account summary for ${esc(r.period)} (UTC). Mode: ${esc(r.metrics?.mode ?? '')}.</p>`,
    narrative,
    '<table cellpadding="6" style="border-collapse:collapse" border="1"><tr><th>Account</th><th>Venue</th><th>Equity</th>'
      + `<th>Day change</th><th>Fees</th><th>Funding</th><th>Risk mode</th></tr>${rows}</table>`,
    breakerList,
    `<p style="font-size:12px;color:#555">This report is generated by software from data in exchange accounts you control. `
      + 'It is not investment advice or a recommendation. Past results do not indicate future results. Digital assets are volatile '
      + `and you can lose all capital allocated to trading. Disclosures v${DISCLOSURE_VERSION}.</p>`,
  ].join('\n');
  return { json: { ...r, to: r.email, subject: subject.slice(0, 90), html, hash_input: `${r.client_id}|${r.period}|${html}` } };
});

// End-of-run summary for the ops channel, counted from the database so it
// covers every batch of the loop.
const r = $input.first().json;
const sent = Number(r.sent ?? 0);
const fallback = Number(r.fallback ?? 0);
return [{ json: { severity: 'INFO', text: `[REPORTS] ${sent} report(s) recorded in this run, ${fallback} used the template fallback` } }];
